<section class="pdm-learn" dir="rtl"><header class="pdm-learn-hero"><div><span class="pdm-learn-kicker">مرجع سریع</span><h1><i class="fas fa-book"></i> واژه‌نامهٔ PdM</h1><p><?= count($terms) ?> اصطلاح فارسی و انگلیسی. جست‌وجو در واژه و تعریف انجام می‌شود.</p></div><nav class="pdm-learn-actions"><a class="pdm-learn-btn" href="<?= pdm_e(pdm_url('learn')) ?>">درس‌ها</a><a class="pdm-learn-btn primary" href="<?= pdm_e(pdm_url('learn','tools')) ?>">ماشین‌حساب‌ها</a></nav></header>
<section class="pdm-learn-panel"><label class="pdm-learn-search">جست‌وجوی واژه<input type="search" placeholder="مثلاً MTBF یا زمان تأمین" data-pdm-glossary autocomplete="off"></label><p class="pdm-learn-muted" data-pdm-count><?= count($terms) ?> اصطلاح</p><div class="pdm-learn-terms" data-pdm-list><?php foreach($terms as $term): $search=mb_strtolower($term['term'].' '.$term['fa'].' '.$term['def'],'UTF-8'); ?><article data-search="<?= pdm_e($search) ?>"><div><strong dir="ltr"><?= pdm_e($term['term']) ?></strong><h3><?= pdm_e($term['fa']) ?></h3></div><p><?= pdm_e($term['def']) ?></p></article><?php endforeach; ?></div><p class="pdm-learn-muted" data-pdm-empty hidden>واژه‌ای پیدا نشد.</p></section></section>
<script>(function(){var i=document.querySelector('[data-pdm-glossary]'),l=document.querySelector('[data-pdm-list]'),c=document.querySelector('[data-pdm-count]'),e=document.querySelector('[data-pdm-empty]');if(!i||!l)return;var a=[].slice.call(l.querySelectorAll('article'));function f(){var q=i.value.trim().toLowerCase(),n=0;a.forEach(function(x){var ok=!q||(x.dataset.search||'').toLowerCase().indexOf(q)>=0;x.hidden=!ok;if(ok)n++;});if(c)c.textContent=n+' اصطلاح';if(e)e.hidden=n>0;}i.addEventListener('input',f);i.addEventListener('keydown',function(x){if(x.key==='Escape'){i.value='';f();}});})();</script>
